from pathlib import Path
p=Path(r"C:\Users\graph\Documents\directeur portaille\secretary.html")
t=p.read_text(encoding="utf-8")
start=t.index("      function secretaryDuplicateRender")
end=t.index("      function updateSecretaryDuplicateSelectedCount", start)
new=r'''      function secretaryDuplicateRender(){const body=document.getElementById('secretaryDuplicateTableBody');if(!body)return;const groups=secretaryDuplicateState.groups,selected=secretaryDuplicateState.selected,rows=[];groups.forEach((g,gi)=>g.records.forEach((r,ri)=>rows.push({r,gi,ri,reasons:g.reasons})));if(!rows.length){body.innerHTML='<tr><td colspan="11" class="text-center text-success py-5"><i class="bi bi-check-circle fs-3 d-block mb-2"></i>Aucun doublon détecté avec les critères actuels.</td></tr>';return;}body.innerHTML=rows.map(({r,gi,ri,reasons})=>{const key=r.source+'|'+r.id,checked=selected.has(key),isKeep=ri===0,ref=secretaryDuplicateEscape(r.reference||r.id),reason=secretaryDuplicateEscape(reasons.join(', '));const linked=r.source==='students'?((inscriptionsData||[]).filter(i=>i.studentId===r.id).length):0;const src=JSON.stringify(String(r.source||'')),rid=JSON.stringify(String(r.id||''));return `<tr><td><input class="form-check-input secretary-duplicate-check" type="checkbox" ${checked?'checked':''} onchange='toggleSecretaryDuplicateSelection(${src},${rid},this.checked)'></td><td><span class="badge bg-secondary">G${gi+1}</span> ${isKeep?'<span class="badge bg-light text-dark ms-1">Conserver suggéré</span>':''}</td><td><strong>${secretaryDuplicateEscape(r.name||'Élève sans nom')}</strong></td><td>${secretaryDuplicateEscape(r.sourceLabel)}${linked?' <small class="text-muted">('+linked+' inscription(s) liée(s))</small>':''}</td><td>${secretaryDuplicateEscape(secretaryBranchLabel(r.branch))}</td><td>${secretaryDuplicateEscape(r.class||'--')}</td><td>${secretaryDuplicateEscape(r.parent||'?')}<br><small class="text-muted">${secretaryDuplicateEscape(r.phone||'')}</small></td><td>${secretaryDuplicateEscape(secretaryDuplicateYear(r.year))}</td><td><small>${ref}</small></td><td><span class="badge ${reasons.some(x=>x.includes('téléphone')||x.includes('référence')||x.includes('naissance'))?'bg-danger':'bg-warning text-dark'}">${reason}</span></td><td><button class="btn btn-sm btn-outline-danger" title="Effacer cet enregistrement" onclick='deleteOneSecretaryDuplicate(${src},${rid})'><i class="bi bi-trash3"></i></button></td></tr>`;}).join('');}
'''
t=t[:start]+new+"\n"+t[end:]
p.write_text(t,encoding="utf-8")
print("repaired")
